# --- Visuals ---
def create_gauge(value, title, min_val=0, max_val=100, color="#0078d4"):
    fig = go.Figure(go.Indicator(
        mode = "gauge+number", value = value,
        title = {'text': title, 'font': {'color': color, 'size': 14}},
        number = {'font': {'color': color, 'size': 20}},
        gauge = {'axis': {'range': [min_val, max_val], 'tickcolor': color}, 'bar': {'color': color}, 'bgcolor': "#fcfcfc", 'bordercolor': "#e0e0e0"}
    ))
    fig.update_layout(paper_bgcolor="rgba(0,0,0,0)", font={'color': "#1e1e1e"}, height=220, margin=dict(l=10, r=10, t=40, b=10))
    return fig

