def login_page():
    _, top_right = st.columns([10, 1])
    with top_right:
        pass

    try:
        import requests
        from streamlit_lottie import st_lottie

        @st.cache_data(show_spinner=False)
        def load_lottieurl(url: str):
            try: return requests.get(url).json()
            except: return None

        lottie_auth = load_lottieurl("https://lottie.host/80e98031-64d4-4a5f-9c04-5cd3c200632a/yR6hP0V2t9.json")

        c1, c2, c3 = st.columns([1, 0.4, 1])
        with c2:
            if lottie_auth:
                st_lottie(lottie_auth, height=140, key="login_lottie")
    except ImportError:
        pass # Degrade gracefully if Lottie library is not found

    st.markdown('<div class="neon-title" style="padding-top:10px;">PolicyNav AI</div>', unsafe_allow_html=True)
    st.markdown('<div class="neon-sub">Secure Entity Interface</div>', unsafe_allow_html=True)
    _, mid, _ = st.columns([1, 0.8, 1])
    with mid:
        login_mode = "Email & Password"

        if login_mode == "Email & Password":
            u_id = st.text_input("EMAIL", placeholder="ENTER EMAIL")
            u_pw = st.text_input("PASSWORD", type="password", placeholder="ENTER PASSWORD")
            if st.button("Sign In", key="login_main", use_container_width=True):
                if u_id and u_pw:
                    is_locked, rem_time = db.is_rate_limited(u_id)
                    if is_locked:
                        st.error(f"Account locked. Try again in {rem_time} seconds due to Brute Force Protection.")
                    else:
                        success, username, is_admin, msg = db.authenticate_user(u_id, u_pw)
                        if success:
                            st.session_state['user_data'] = {"sub": u_id, "username": username, "is_admin": is_admin}
                            from utils import ADMIN_EMAIL
                            if u_id == ADMIN_EMAIL:
                                st.session_state['is_in_admin_dashboard'] = True
                                st.session_state['admin_verified'] = False
