with open('knowledge_graph.py', 'w', encoding='utf-8') as f:
    f.write("""
import streamlit as st
import os
from collections import Counter
import networkx as nx

@st.cache_resource(show_spinner=False)
def get_spacy_nlp():
    try:
        import spacy
        return spacy.load("en_core_web_sm")
    except Exception as e:
        st.warning(f"Could not initialize localized spaCy model (Knowledge Graph features may be disabled): {str(e)}")
        return None

APP_DIR = os.environ.get('APP_DIR', '.')

def generate_interactive_graph(docs, policy_name="all_policies"):
    nlp = get_spacy_nlp()
    if not docs or not nlp: return None

    G = nx.DiGraph()
    # Processing top docs (limit to prevent huge graphs)
    max_docs = min(len(docs), 150)

    color_map = {
        'ORG': '#3498db', 'LAW': '#f39c12',
        'GPE': '#e74c3c', 'PERSON': '#2ecc71', 'PRODUCT': '#9b59b6',
        'DATE': '#00bcd4', 'EVENT': '#ff9800', 'Entity': '#d2d7d3'
    }

    processed_docs = []

    # Extract triples
    for i in range(max_docs):
        text = docs[i]['content'][:1000]
        doc = nlp(text)
        processed_docs.append(doc)

        for sent in doc.sents:
            subj = None
            verb = None
            obj = None

            for token in sent:
                if "subj" in token.dep_ and not subj:
                    subj = token
                elif token.pos_ == "VERB" and not verb:
                    verb = token
                elif "obj" in token.dep_ and not obj:
                    obj = token

            if subj and verb and obj:
                s_text = subj.text.strip()
                v_text = verb.lemma_.upper().replace(" ", "_")
                o_text = obj.text.strip()

                # Basic filtering
                invalid_words = ['they', 'this', 'that', 'which', 'who', 'what', 'it', 'he', 'she', 'we', 'i', 'you']
                if len(s_text) > 2 and len(o_text) > 2 and s_text.lower() not in invalid_words and o_text.lower() not in invalid_words:

                    s_group = 'Entity'
                    o_group = 'Entity'

                    # Try to assign a named entity group if it matches
                    for ent in doc.ents:
                        if s_text in ent.text or ent.text in s_text:
                            s_group = ent.label_
                        if o_text in ent.text or ent.text in o_text:
                            o_group = ent.label_

                    # Add nodes
                    if s_text not in G:
                        G.add_node(s_text, label=s_text.title(), group=s_group, color=color_map.get(s_group, color_map['Entity']))
                    if o_text not in G:
                        G.add_node(o_text, label=o_text.title(), group=o_group, color=color_map.get(o_group, color_map['Entity']))

                    # Add edge
                    if not G.has_edge(s_text, o_text):
                        G.add_edge(s_text, o_text, label=v_text, title=v_text)

    # Fallback to co-occurrence if graph is too sparse (less than 5 edges)
    if G.number_of_edges() < 5:
        G.clear()
        entity_counts = Counter()
        for doc in processed_docs:
            entities = [ent.text.strip() for ent in doc.ents if ent.label_ in color_map]
            entity_counts.update(entities)

        top_entities = {name for name, count in entity_counts.items() if count >= 2}

        for doc in processed_docs:
            current_entities = [ent for ent in doc.ents if ent.text.strip() in top_entities]

            for ent in current_entities:
                name = ent.text.strip()
                if name not in G:
                    G.add_node(name, label=name, group=ent.label_, color=color_map.get(ent.label_, color_map['Entity']))

            for j in range(len(current_entities)):
                for k in range(j + 1, len(current_entities)):
                    src = current_entities[j].text.strip()
                    tgt = current_entities[k].text.strip()
                    if src != tgt and not G.has_edge(src, tgt) and not G.has_edge(tgt, src):
                        G.add_edge(src, tgt, label="ASSOCIATED_WITH", title="ASSOCIATED_WITH")

    # Limit to top connected components if graph is too large to speed up physics
    if G.number_of_nodes() > 100:
        components = sorted(nx.weakly_connected_components(G), key=len, reverse=True)
        keep_nodes = set()
        for c in components:
            if len(keep_nodes) >= 100: break
            keep_nodes.update(c)
        G = G.subgraph(keep_nodes).copy()

    from pyvis.network import Network
    import tempfile
    import uuid

    # Changed to match image: White background, black text, undirected edges
    net = Network(height="700px", width="100%", bgcolor="#ffffff", font_color="black", directed=False)

    # Configure physics for smooth layout
    net.force_atlas_2based(gravity=-50, central_gravity=0.01, spring_length=100, spring_strength=0.08, damping=0.4, overlap=0)

    for node_id, data in G.nodes(data=True):
        degree = G.degree(node_id)
        # Size nodes dynamically based on connections, like the image
        node_size = max(10, min(50, 10 + (degree * 4)))

        net.add_node(
            node_id,
            label=data.get('label', node_id)[:30],
            size=node_size,
            shape="dot",
            # Made all nodes the exact same blue color to match the reference image
            color="#1f77b4",
            title=f"Connections: {degree}"
        )

    for src, tgt, data in G.edges(data=True):
        net.add_edge(
            src,
            tgt,
            title=data.get('label', '')
        )

    # Advanced visualization settings to highlight neighboring nodes/edges on click
    # and provide attractive premium interactions and physics
    options = \"\"\"
    var options = {
      "nodes": {
        "borderWidth": 1,
        "borderWidthSelected": 4,
        "color": {
          "border": "#135d92",
          "background": "#1f77b4",
          "highlight": {
            "border": "#c92a2a",
            "background": "#fa5252"
          },
          "hover": {
            "border": "#0f4c75",
            "background": "#3282b8"
          }
        },
        "font": {
          "color": "#111827",
          "size": 15,
          "face": "Arial",
          "background": "rgba(255, 255, 255, 0.7)"
        },
        "shadow": {
          "enabled": true,
          "color": "rgba(0,0,0,0.15)",
          "size": 10,
          "x": 3,
          "y": 3
        }
      },
      "edges": {
        "color": {
          "color": "#d1d5db",
          "highlight": "#f03e3e",
          "hover": "#1f77b4",
          "inherit": false,
          "opacity": 0.8
        },
        "width": 1.5,
        "hoverWidth": 2.5,
        "selectionWidth": 3,
        "smooth": {
          "type": "continuous",
          "forceDirection": "none"
        }
      },
      "interaction": {
        "hover": true,
        "hoverConnectedEdges": true,
        "selectConnectedEdges": true,
        "tooltipDelay": 100,
        "zoomView": true,
        "dragView": true
      },
      "physics": {
        "forceAtlas2Based": {
          "gravitationalConstant": -70,
          "centralGravity": 0.015,
          "springLength": 110,
          "springConstant": 0.08,
          "damping": 0.6,
          "avoidOverlap": 0.1
        },
        "minVelocity": 0.75,
        "solver": "forceAtlas2Based"
      }
    }
    \"\"\"
    net.set_options(options)

    # Save to a temporary file
    temp_path = os.path.join(tempfile.gettempdir(), f"graph_{uuid.uuid4().hex}.html")
    net.save_graph(temp_path)

    with open(temp_path, 'r', encoding='utf-8') as f:
        html_code = f.read()

    return html_code
""")

