            fig_r = px.bar(section_ratings, x='Section', y='Rating', color='Rating', color_continuous_scale=px.colors.sequential.Viridis, range_y=[0, 5])
            fig_r.update_layout(height=300, margin=dict(t=10, b=10, l=10, r=10), paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)")
