        with h_col4:
            st.markdown("<div style='margin-top: 10px;'></div>", unsafe_allow_html=True)
            if st.button("🚪 Exit Admin", type="primary", use_container_width=True):
                st.session_state['admin_view'] = 'dashboard'
                st.session_state['user_data'] = None
                st.session_state['is_in_admin_dashboard'] = False
                st.session_state['admin_verified'] = False
                st.rerun()

        st.markdown("<hr style='border: 1px solid #e0e0e0; margin-top: 10px; margin-bottom: 30px;'>", unsafe_allow_html=True)
        if st.session_state.get('admin_verified', False) and st.session_state.get('admin_view') == 'doc_manage':
            from views.doc_manage import doc_manage_page
