def extract_pdf_text(file_obj):
    import PyPDF2
    text = ""
    try:
        for page in PyPDF2.PdfReader(file_obj).pages:
            extracted = page.extract_text()
            if extracted: text += extracted + "\\n"
    except Exception as e:
        print(f"PDF Extraction Error: {e}")
    return text

