import subprocess
import time
from pyngrok import ngrok
from pyngrok.exception import PyngrokNgrokError # Corrected import path
from google.colab import userdata

# 1. Retrieve and set Ngrok Authtoken from Colab Secrets
try:
    NGROK_AUTHTOKEN = userdata.get('NGROK_AUTHTOKEN')
    if not NGROK_AUTHTOKEN:
        raise ValueError("NGROK_AUTHTOKEN is not set in Colab Secrets.")
    ngrok.set_auth_token(NGROK_AUTHTOKEN)
except ValueError as ve:
    print(f"❌ ERROR: {ve}")
    print("Go to the 'Key' icon on the left sidebar and add your ngrok authtoken there.")
    exit() # Exit if authtoken is not found or empty
except Exception as e:
    print(f"❌ An unexpected error occurred while retrieving NGROK_AUTHTOKEN: {e}")
    exit()

# 2. Kill any existing ngrok sessions to avoid 'Too many sessions' error
try:
    tunnels = ngrok.get_tunnels()
    for t in tunnels:
        ngrok.disconnect(t.public_url)
except PyngrokNgrokError as e:
    print(f"❌ NGROK ERROR: {e}")
    print("Please ensure your NGROK_AUTHTOKEN in Colab Secrets is valid and has not been revoked.")
    exit()
except Exception as e:
    print(f"❌ An unexpected error occurred during ngrok session management: {e}")
    exit()

# 3. Launch Streamlit as a background process
# Using 'python -m streamlit' fixes the 'FileNotFoundError' you encountered
print("🚀 Initializing PolicyNav AI Engine...")
process = subprocess.Popen(
    ["python", "-m", "streamlit", "run", "app.py", "--server.port", "8501", "--server.headless", "true"]
)

# 4. Wait for the server to initialize (LLMs take a moment to boot)
time.sleep(10)

# 5. Connect the Tunnel
try:
    public_url = ngrok.connect(8501).public_url
    print("\n" + "="*30)
    print("🎉 APPLICATION SUCCESSFULLY LIVE")
    print(f"🔗 URL: {public_url}")
    print("="*30)
except PyngrokNgrokError as e:
    print(f"❌ NGROK CONNECTION FAILED: {e}")
    print("Ensure your ngrok authtoken is correct and you have an active ngrok account.")
except Exception as e:
    print(f"❌ An unexpected error occurred while connecting ngrok tunnel: {e}")

# --- CELL 8: GRACEFUL SHUTDOWN ---
import os
import signal
from pyngrok import ngrok

print("🛑 Shutting down PolicyNav AI...")

# 1. Disconnect all ngrok tunnels
try:
    tunnels = ngrok.get_tunnels()
    for t in tunnels:
        ngrok.disconnect(t.public_url)
    print("✅ Ngrok tunnels disconnected.")
except Exception as e:
    print(f"⚠️ Error disconnecting tunnels: {e}")

# 2. Terminate the Streamlit process
try:
    # We reference the 'process' variable from Cell 7
    process.terminate()
    process.wait(timeout=5)
    print("✅ Streamlit server process terminated.")
except NameError:
    print("⚠️ 'process' variable not found. Attempting system-level kill...")
    # Fallback: Kill any process running on port 8501
    os.system("fuser -k 8501/tcp")
except Exception as e:
    print(f"❌ Error during shutdown: {e}")

print("\nSystem is now idle. You can safely restart Cell 7 if needed.")